      for (int x=0; x<w; x++) { seed(x,0); seed(x,h-1); }
      for (int y=0; y<h; y++) { seed(0,y); seed(w-1,y); }
      int[] dx={1,-1,0,0}; int[] dy={0,0,1,-1};
      while(queue.Count>0) {
        int i=queue.Dequeue(), x=i%w, y=i/w;
        for(int k=0;k<4;k++) { int nx=x+dx[k], ny=y+dy[k]; if(nx<0||ny<0||nx>=w||ny>=h) continue; int ni=ny*w+nx; if(!seen[ni] && IsExteriorCandidate(dst.GetPixel(nx,ny))) { seen[ni]=true; queue.Enqueue(ni); } }
      }
