        dst.SetPixel(x,y, Color.FromArgb(a, 56, 34, 40));
      }
      dst.Save(output, ImageFormat.Png);
    }
  }
  static bool IsExteriorCandidate(Color c) {
    int max=Math.Max(c.R,Math.Max(c.G,c.B)); int min=Math.Min(c.R,Math.Min(c.G,c.B));
    return max >= 82 && (max-min) <= 38;
  }
}
