using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
public static class CheckerboardAlpha {
  static bool Candidate(Color c) {
    int max = Math.Max(c.R, Math.Max(c.G, c.B));
    int min = Math.Min(c.R, Math.Min(c.G, c.B));
    int luminance = (c.R * 299 + c.G * 587 + c.B * 114) / 1000;
    return luminance >= 175 && (max - min) <= 24;
  }
  public static void Convert(string sourcePath, string targetPath) {
    using (var src = new Bitmap(sourcePath)) {
      int w = src.Width, h = src.Height;
      var visited = new bool[w * h];
      var queue = new Queue<int>();
      Action<int,int> seed = (x,y) => {
        int i = y * w + x;
        if ("'!visited[i] && Candidate(src.GetPixel(x,y))) { visited[i] = true; queue.Enqueue(i); }
      };
      for (int x=0; x<w; x++) { seed(x,0); seed(x,h-1); }
      for (int y=0; y<h; y++) { seed(0,y); seed(w-1,y); }
      int[] dx = {-1,0,1,-1,1,-1,0,1};
      int[] dy = {-1,-1,-1,0,0,1,1,1};
      while (queue.Count > 0) {
        int i = queue.Dequeue(); int x = i % w, y = i / w;
        for (int k=0; k<8; k++) {
