using System.Drawing;
using System.Drawing.Imaging;
public static class CheckerAlpha {
  private static bool IsBackground(Color c) {
    int max = Math.Max(c.R, Math.Max(c.G, c.B));
    int min = Math.Min(c.R, Math.Min(c.G, c.B));
    return min >= 208 && (max - min) <= 14;
  }
  public static void Extract(string input, string output) {
    using (var src = new Bitmap(input)) {
      int w = src.Width, h = src.Height;
      var bg = new bool[w * h];
      var queued = new bool[w * h];
      var q = new Queue<int>();
      Action<int,int> seed = (x,y) => {
        int idx = y*w+x;
        if ("'!queued[idx] && IsBackground(src.GetPixel(x,y))) { queued[idx]=true; q.Enqueue(idx); }
      };
      for (int x=0; x<w; x++) { seed(x,0); seed(x,h-1); }
      for (int y=0; y<h; y++) { seed(0,y); seed(w-1,y); }
      int[] dx = {1,-1,0,0}; int[] dy = {0,0,1,-1};
