        int x=idx%w, y=idx/w;
        for (int k=0;k<4;k++) { int nx=x+dx[k], ny=y+dy[k]; if(nx<0||nx>=w||ny<0||ny>=h) continue; int ni=ny*w+nx; if(!queued[ni] && IsBackground(src.GetPixel(nx,ny))) { queued[ni]=true; q.Enqueue(ni); } }
      }
      using (var dst = new Bitmap(w,h,PixelFormat.Format32bppArgb)) {
