using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;

public static class AlphaCutout {
  private static bool IsBackgroundCandidate(Color c) {
    int max = Math.Max(c.R, Math.Max(c.G, c.B));
    int min = Math.Min(c.R, Math.Min(c.G, c.B));
    return min >= 205 && (max - min) <= 24;
  }

  public static void Convert(string path) {
    using (var src = new Bitmap(path)) {
      int w = src.Width, h = src.Height;
      var bg = new bool[w, h];
      var q = new Queue<Point>();
      Action<int,int> seed = (x,y) => {
        if ("'!bg[x,y] && IsBackgroundCandidate(src.GetPixel(x,y))) {
          bg[x,y] = true;
          q.Enqueue(new Point(x,y));
        }
      };
      for (int x=0; x<w; x++) { seed(x,0); seed(x,h-1); }
      for (int y=0; y<h; y++) { seed(0,y); seed(w-1,y); }
      int[] dx = {1,-1,0,0};
      int[] dy = {0,0,1,-1};
      while (q.Count > 0) {
        Point p = q.Dequeue();
        for (int k=0; k<4; k++) {
          int nx=p.X+dx[k], ny=p.Y+dy[k];
          if (nx<0 || nx>=w || ny<0 || ny>=h || bg[nx,ny]) continue;
          if (IsBackgroundCandidate(src.GetPixel(nx,ny))) {
            bg[nx,ny]=true;
            q.Enqueue(new Point(nx,ny));
          }
        }
      }
      using (var dst = new Bitmap(w,h,PixelFormat.Format32bppArgb)) {
        for (int y=0; y<h; y++) {
          for (int x=0; x<w; x++) {
            Color c = src.GetPixel(x,y);
            if (bg[x,y]) { dst.SetPixel(x,y,Color.FromArgb(0,0,0,0)); continue; }
            bool edge=false;
            for (int oy=-1; oy<=1 && !edge; oy++) for (int ox=-1; ox<=1; ox++) {
              int nx=x+ox, ny=y+oy;
              if (nx>=0 && nx<w && ny>=0 && ny<h && bg[nx,ny]) { edge=true; break; }
            }
            if (!edge) { dst.SetPixel(x,y,Color.FromArgb(255,c.R,c.G,c.B)); continue; }
            int distance = Math.Max(255-c.R, Math.Max(255-c.G,255-c.B));
            int alpha = Math.Max(24, Math.Min(255, distance * 3));
            double a = alpha / 255.0;
            int rr = Math.Max(0, Math.Min(255, (int)Math.Round((c.R - 255*(1-a))/a)));
            int gg = Math.Max(0, Math.Min(255, (int)Math.Round((c.G - 255*(1-a))/a)));
            int bb = Math.Max(0, Math.Min(255, (int)Math.Round((c.B - 255*(1-a))/a)));
            dst.SetPixel(x,y,Color.FromArgb(alpha,rr,gg,bb));
          }
        }
        string tmp = path + ".alpha.png";
        dst.Save(tmp,ImageFormat.Png);
        src.Dispose();
        System.IO.File.Copy(tmp,path,true);
        System.IO.File.Delete(tmp);
      }
    }
