using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;

public static class AlphaCutout {
    public static void Run(string source, string target) {
        using (var src = new Bitmap(source)) {
            int w = src.Width, h = src.Height, n = w * h;
            var pixels = new Color[n];
            var candidate = new bool[n];
            var exterior = new bool[n];
            var queue = new int[n];
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    int i = y * w + x;
                    Color c = src.GetPixel(x, y);
                    pixels[i] = c;
                    int min = Math.Min(c.R, Math.Min(c.G, c.B));
                    int max = Math.Max(c.R, Math.Max(c.G, c.B));
                    candidate[i] = min >= 150 && (max - min) <= 22;
                }
            }
            int head = 0, tail = 0;
            Action<int> seed = i => { if (candidate[i] && "'!exterior[i]) { exterior[i] = true; queue[tail++] = i; } };
            for (int x = 0; x < w; x++) { seed(x); seed((h - 1) * w + x); }
            for (int y = 0; y < h; y++) { seed(y * w); seed(y * w + w - 1); }
            while (head < tail) {
                int i = queue[head++], x = i % w, y = i / w;
                int j;
                if (x > 0) { j = i - 1; if (candidate[j] && !exterior[j]) { exterior[j] = true; queue[tail++] = j; } }
                if (x + 1 < w) { j = i + 1; if (candidate[j] && !exterior[j]) { exterior[j] = true; queue[tail++] = j; } }
                if (y > 0) { j = i - w; if (candidate[j] && !exterior[j]) { exterior[j] = true; queue[tail++] = j; } }
                if (y + 1 < h) { j = i + w; if (candidate[j] && !exterior[j]) { exterior[j] = true; queue[tail++] = j; } }
            }
            var visited = new bool[n];
            for (int start = 0; start < n; start++) {
                if (!candidate[start] || exterior[start] || visited[start]) continue;
                var component = new List<int>();
