                    Color c = pixels[i]; int mn = Math.Min(c.R, Math.Min(c.G, c.B)); int mx = Math.Max(c.R, Math.Max(c.G, c.B));
                    if (mn >= 245 && mx - mn <= 12) hasWhite = true;
                    if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y;
                    int j;
