                    if (x+1<w) { j=i+1; if(candidate[j]&&!exterior[j]&&!visited[j]){visited[j]=true;queue[tail++]=j;} }
                    if (y>0) { j=i-w; if(candidate[j]&&!exterior[j]&&!visited[j]){visited[j]=true;queue[tail++]=j;} }
                    if (y+1<h) { j=i+w; if(candidate[j]&&!exterior[j]&&!visited[j]){visited[j]=true;queue[tail++]=j;} }
                }
                if (hasWhite && component.Count >= 100 && (maxX-minX+1) >= 18 && (maxY-minY+1) >= 18) {
                    foreach (int i in component) exterior[i] = true;
                }
            }
            using (var dst = new Bitmap(w, h, PixelFormat.Format32bppArgb)) {
                for (int y = 0; y < h; y++) {
                    for (int x = 0; x < w; x++) {
                        int i = y * w + x; Color c = pixels[i];
                        if (!exterior[i]) { dst.SetPixel(x, y, Color.FromArgb(255, c.R, c.G, c.B)); continue; }
                        int mn = Math.Min(c.R, Math.Min(c.G, c.B));
                        int a = Math.Max(0, Math.Min(255, (255 - mn) * 255 / 95));
                        if (a <= 2) { dst.SetPixel(x, y, Color.FromArgb(0, 0, 0, 0)); continue; }
                        double af = a / 255.0;
                        int rr = (int)Math.Round((c.R - 255.0 * (1.0 - af)) / af);
